// Page «Главная» (/) of the public site, written by the page composer v3 (V3-12).
// Sections: header-menu-first, hero-split, catalog-grid, contacts-centered, footer-contact-first.
import { useEffect } from "react";
import { useSitePhotos } from "@wizard/ui-kit/v3/headless";
import HeaderMenuFirst from "../../patterns/header-menu-first";
import HeroSplit from "../../patterns/hero-split";
import CatalogGrid from "../../patterns/catalog-grid";
import ContactsCentered from "../../patterns/contacts-centered";
import FooterContactFirst from "../../patterns/footer-contact-first";

export default function HomePage() {
  const photo = useSitePhotos();
  useEffect(() => {
    const id = location.hash.slice(1);
    const target = id ? document.getElementById(id) : null;
    if (!target) return;
    target.scrollIntoView();
    const keep = new ResizeObserver(() => target.scrollIntoView());
    keep.observe(document.body);
    const stop = () => keep.disconnect();
    const timer = setTimeout(stop, 3000);
    for (const e of ["wheel", "touchstart", "keydown"]) addEventListener(e, stop, { once: true, passive: true });
    return () => {
      clearTimeout(timer);
      stop();
      for (const e of ["wheel", "touchstart", "keydown"]) removeEventListener(e, stop);
    };
  }, []);
